export const MessageConversationTypePrivate = 1;
export const MessageConversationTypeSystem = 2;
export const MessageConversationTypeSystemDirect = 3;

export interface MessageConversation {
  id: number;
  type: number;
  peer_id: number;
  peer_username: string;
  peer_nickname: string;
  peer_email: string;
  last_message: string;
  last_message_time: string | null;
  unread_count: number;
}

export interface MessageConversationView {
  id: number;
  type: number;
  peerId: number;
  peerUsername: string;
  peerNickname: string;
  peerEmail: string;
  avatarUrl?: string;
  lastMessage: string;
  lastMessageTime: string;
  /** 原始时间戳（ms），用于在不依赖格式化字符串的情况下比较新旧 */
  lastMessageTimeMs?: number;
  unreadCount: number;
  isTemp?: boolean;
}

export interface Message {
  id: number;
  conversation_id: number;
  sender_id: number;
  sender_username: string;
  sender_nickname: string;
  sender_email: string;
  content: string;
  type: number;
  is_read: boolean;
  read_time: string | null;
  is_recalled: boolean;
  create_time: string;
}

export interface MessageView {
  id: number;
  conversationId: number;
  senderId: number;
  senderUsername: string;
  senderNickname: string;
  senderEmail: string;
  avatarUrl?: string;
  content: string;
  type: number;
  isRead: boolean;
  readTime: string | null;
  isRecalled: boolean;
  createTime: string;
  createTimeMs: number;
  isSelf: boolean;
}

// ─── 接口返回结构（供 apis/message.ts 声明返回类型）─────────────────

/** 分页接口通用返回体：公告列表（/message/system/admin/list）与后台会话列表共用 list/total/page 三段式 */
export interface PagedData<Item> {
  list: Item[];
  total: number;
  page: number;
}

/** 获取/创建会话接口（/message/create）返回数据 */
export interface CreateConversationResponse {
  conversation_id: number;
  peer_id: number;
}

export interface MessageSendRequest {
  conversation_id: number;
  content: string;
}

export interface MessageReadRequest {
  conversation_id: number;
}

// Admin system message types
export interface SystemMessageAdminItem {
  id: number;
  content: string;
  sender_id: number;
  sender_username: string;
  sender_nickname: string;
  create_time: string;
  expire_time: string | null; // 过期时间 ISO 字符串，null 表示永久
  hide_before_register: boolean; // 为 true 时对注册晚于本公告的用户隐藏
}

export interface SystemMessageAdminListResponse {
  list: SystemMessageAdminItem[];
  total: number;
  page: number;
}

// 请求体：发送 / 编辑全局公告（expire_time 为 ISO 字符串，null 表示永久）
export interface SystemMessageSendRequest {
  content: string;
  expire_time: string | null;
  hide_before_register: boolean;
}

export interface SystemMessageEditRequest {
  id: number;
  content: string;
  expire_time: string | null;
  hide_before_register: boolean;
}

// Admin direct system message types
export interface AdminSearchUser {
  id: number;
  username: string;
  nickname: string;
  email: string;
}

export interface AdminDirectSendResponse {
  conversation_id: number;
  message_id: number;
}

// Virtual conversation ID for the global broadcast channel in admin UI
export const ADMIN_BROADCAST_CONV_ID = -1;
